// ===== Kelly Crunch rules engine (from Vol 1) (shared by game, solver, tests) =====
// Board: array of columns; each column is an array top->bottom of cells.
// cell: {k:'c',s:0|1|2,c:color,f:0|1,id} critter | {k:'b',n:fed,id} bomb | {k:'x',id} spiky | {k:'g',id} gem crystal
const KC=(()=>{
let NID=1;
const mk=(k,s,c)=>k==='c'?{k:'c',s,c,f:0,id:NID++}:{k,n:0,id:NID++};
const cl=x=>x?Object.assign({},x):x;
const clone=B=>B.map(col=>col.map(cl));
const ck=x=>x.k==='c'?('sml'[x.s]+(x.f?'*':'')+x.c):x.k==='b'?'b'+x.n:x.k;
const key=B=>B.map(col=>col.map(ck).join(',')).join('|');
const count=B=>B.reduce((a,col)=>a+col.length,0);
const canGrab=(B,c)=>{const col=B[c];if(!col.length)return 'empty';const x=col[col.length-1];return x.k==='x'?'spike':x.k==='g'?'gem':'ok'};
const grab=(B,c)=>B[c].pop();
const compat=(e,f)=>!!e&&!!f&&f.k==='c'&&((e.k==='c'&&f.s===e.s-1)||e.k==='b');
// eater = out[i] (always last of out) eats food. Returns event.
function eatInto(out,i,food,seeds,seedSet){const e=out[i];const ev={eater:e.id,food:food.id,foodFull:food.f,chain:0,boom:0};
 if(e.k==='b'){e.n++;if(e.n>=2){seeds.push(e.id);seedSet.add(e.id);ev.boom=1}return ev}
 if(e.f||food.f){seeds.push(e.id);seedSet.add(e.id);ev.boom=1;return ev}
 e.f=1;const a=out[i-1];
 if(a&&a.k==='c'&&a.s===e.s+1&&!seedSet.has(a.id)){out.splice(i,1);seeds.push(a.id);seedSet.add(a.id);ev.chain=a.id;ev.boom=1}
 return ev}
// Spit item into column c. Returns {kind:'eat'|'stack', ev, seeds, row}
function spit(B,c,item){const col=B[c],seeds=[],ss=new Set();const b=col[col.length-1];
 if(compat(b,item)){const row=col.length-1;const ev=eatInto(col,col.length-1,item,seeds,ss);return{kind:'eat',ev,seeds,row,eater:b.id}}
 col.push(item);return{kind:'stack',seeds,row:col.length-1}}
function locate(B){const m=new Map();B.forEach((col,c)=>col.forEach((x,r)=>{if(x)m.set(x.id,[c,r])}));return m}
const at=(B,c,r)=>(c>=0&&c<B.length&&r>=0&&r<B[c].length)?B[c][r]:null;
// Explode seeds. Mutates B (sets nulls). Returns list of removed {c,r,cell,why}
function popPhase(B,seeds){const L=locate(B),rem=new Map(),bombQ=[];
 const add=(c,r,why)=>{const x=at(B,c,r);if(!x||rem.has(x.id))return null;rem.set(x.id,{c,r,cell:x,why});return x};
 for(const id of seeds){const p=L.get(id);if(!p)continue;const x=at(B,p[0],p[1]);if(!x)continue;
  if(x.k==='b'){if(!rem.has(x.id)){add(p[0],p[1],'bomb');bombQ.push(p)}continue}
  if(rem.has(x.id))continue;const st=[p];add(p[0],p[1],'pop');
  while(st.length){const [c,r]=st.pop();for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){const y=at(B,c+dc,r+dr);if(y&&y.k==='c'&&y.s===x.s&&y.c===x.c&&!rem.has(y.id)){add(c+dc,r+dr,'pop');st.push([c+dc,r+dr])}}}}
 while(bombQ.length){const [c,r]=bombQ.pop();for(let dc=-1;dc<=1;dc++)for(let dr=-1;dr<=1;dr++){const y=at(B,c+dc,r+dr);if(!y||rem.has(y.id))continue;add(c+dc,r+dr,y.k==='b'?'bomb':'blast');if(y.k==='b')bombQ.push([c+dc,r+dr])}}
 for(const v of [...rem.values()]){if(v.why!=='pop')continue;for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){const y=at(B,v.c+dc,v.r+dr);if(y&&(y.k==='x'||y.k==='g')&&!rem.has(y.id))add(v.c+dc,v.r+dr,'shatter')}}
 const out=[...rem.values()];for(const v of out)B[v.c][v.r]=null;return out}
// Critters climb into gaps; climbing critters may be eaten by compatible ones above.
function climbPhase(B){const seeds=[],ss=new Set(),moves=[],eats=[];
 B.forEach((col,c)=>{if(!col.some(x=>!x)){return}const out=[];let gap=false;
  col.forEach((x,r)=>{if(!x){gap=true;return}
   if(gap&&out.length&&compat(out[out.length-1],x)&&!ss.has(out[out.length-1].id)){const eRow=out.length-1;const ev=eatInto(out,out.length-1,x,seeds,ss);ev.c=c;ev.from=r;ev.to=eRow;eats.push(ev);return}
   if(out.length!==r)moves.push({id:x.id,c,from:r,to:out.length});out.push(x);gap=false});
  B[c]=out});
 return{seeds,moves,eats}}
// Full resolution (no animation). Returns stats.
function settle(B,seeds){let chain=0,popped=0,phases=[];while(seeds.length){const p=popPhase(B,seeds);chain++;popped+=p.length;const cp=climbPhase(B);phases.push({p,cp});seeds=cp.seeds}
 B.forEach((col,c)=>{if(col.some(x=>!x))B[c]=col.filter(x=>x)});return{chain,popped,phases}}
function move(B,from,to){if(canGrab(B,from)!=='ok')return null;const it=grab(B,from);const r=spit(B,to,it);const s=settle(B,r.seeds);return{spit:r,settle:s}}
function legal(B){const m=[];for(let f=0;f<B.length;f++){if(canGrab(B,f)!=='ok')continue;for(let t=0;t<B.length;t++)m.push([f,t])}return m}
// BFS solver: shortest sequence of (from,to) that empties the board.
function solve(B0,maxStates=400000,maxDepth=40){const k0=key(B0);if(count(B0)===0)return{moves:[],states:1};const seen=new Map([[k0,null]]);let fr=[B0],keys=[k0],depth=0,states=1;
 while(fr.length&&depth<maxDepth){depth++;const nf=[],nk=[];
  for(let i=0;i<fr.length;i++){const B=fr[i];for(const [f,t] of legal(B)){const N=clone(B);move(N,f,t);const k=key(N);if(seen.has(k))continue;seen.set(k,[keys[i],f,t]);states++;
    if(count(N)===0){const path=[];let kk=k;while(seen.get(kk)){const [pk,ff,tt]=seen.get(kk);path.unshift([ff,tt]);kk=pk}return{moves:path,states}}
    if(states>maxStates)return{moves:null,states,capped:true};nf.push(N);nk.push(k)}}
  fr=nf;keys=nk}
 return{moves:null,states}}
// Parse puzzle spec: columns as strings top->bottom, tokens like "s0 m1* l2 b x g"
function parse(spec){return spec.map(col=>col.trim()?col.trim().split(/\s+/).map(t=>{if(t[0]==='b')return mk('b');if(t==='x')return mk('x');if(t==='g')return mk('g');const s='sml'.indexOf(t[0]);const x=mk('c',s,+t[1]);if(t[2]==='*')x.f=1;return x}):[])}
return{mk,clone,key,count,canGrab,grab,spit,popPhase,climbPhase,settle,move,legal,solve,parse,compat,locate,ck,get NID(){return NID}}})();


