 pop(k=0,big=false){const n=60+PENT[Math.min(PENT.length-1,k)];const f=440*Math.pow(2,(n-69)/12);AU.tone(f*1.5,.16,'square',.12,f*3);AU.tone(f,.2,'triangle',.18,f*.5);AU.noise(big?.25:.12,big?.25:.15,big?1400:3000,'lowpass',0,300)},
