 charge(){AU.tone(200,.6,'sawtooth',.08,800)},
 freeze(){for(let i=0;i<6;i++)AU.tone(2000+i*260,.12,'sine',.06,null,i*.04);AU.noise(.4,.08,6000,'highpass')},
