/* ---- music: step sequencer with per-world tracks, composed from seeded motifs ---- */
const MUS=(()=>{
 const mf=m=>440*Math.pow(2,(m-69)/12);
 const SC={maj:[0,2,4,5,7,9,11],min:[0,2,3,5,7,8,10],dor:[0,2,3,5,7,9,10],mix:[0,2,4,5,7,9,10],lyd:[0,2,4,6,7,9,11]};
 // chord degrees per bar (8 bars)
 const T={
  title:{bpm:112,key:60,sc:'maj',prog:[0,5,3,4,0,5,3,4],lead:'bell',bass:'round',drums:'pop',pad:1,seed:11},
  map:{bpm:96,key:62,sc:'maj',prog:[0,3,4,0,5,3,1,4],lead:'marimba',bass:'round',drums:'soft',pad:1,seed:23},
  w1:{bpm:120,key:60,sc:'maj',prog:[0,4,5,3,0,4,3,4],lead:'marimba',bass:'bounce',drums:'pop',pad:0,seed:31},
  w2:{bpm:100,key:57,sc:'dor',prog:[0,3,0,6,0,3,4,4],lead:'pluck',bass:'swamp',drums:'swing',pad:1,seed:47},
  w3:{bpm:110,key:55,sc:'mix',prog:[0,6,3,0,0,6,3,4],lead:'whistle',bass:'gallop',drums:'gallop',pad:0,seed:59},
  w4:{bpm:92,key:64,sc:'lyd',prog:[0,1,0,1,5,4,3,4],lead:'bell',bass:'round',drums:'soft',pad:1,seed:71},
  w5:{bpm:124,key:62,sc:'maj',prog:[0,3,4,5,0,3,1,4],lead:'brass',bass:'march',drums:'march',pad:1,seed:83},
  boss1:{bpm:140,key:57,sc:'min',prog:[0,5,3,4,0,5,6,4],lead:'square',bass:'drive',drums:'rock',pad:0,seed:101},
  boss2:{bpm:136,key:55,sc:'dor',prog:[0,6,5,4,0,6,3,4],lead:'square',bass:'drive',drums:'rock',pad:0,seed:113},
  boss3:{bpm:144,key:52,sc:'min',prog:[0,3,5,4,0,3,6,4],lead:'brass',bass:'drive',drums:'rock',pad:0,seed:127},
  boss4:{bpm:132,key:59,sc:'min',prog:[0,5,6,4,0,5,3,4],lead:'bell',bass:'drive',drums:'rock',pad:1,seed:139},
  boss5:{bpm:148,key:50,sc:'min',prog:[0,5,3,4,0,6,3,4],lead:'brass',bass:'drive',drums:'rock',pad:1,seed:151},
  endless:{bpm:118,key:60,sc:'mix',prog:[0,6,3,4,0,6,5,4],lead:'square',bass:'bounce',drums:'pop',pad:0,seed:163},
  ending:{bpm:100,key:60,sc:'maj',prog:[0,4,5,3,0,4,3,4],lead:'bell',bass:'round',drums:'soft',pad:1,seed:179}};
 function rng(s){return()=>{s=(s*1103515245+12345)&0x7fffffff;return s/0x7fffffff}}
 function compose(tr){if(tr.mel)return;const r=rng(tr.seed);const sc=SC[tr.sc];
  const motif=()=>{const out=[];let deg=ri2(r,0,4);for(let s=0;s<32;s++){const on=s%4===0?r()<.85:s%2===0?r()<.45:r()<.18;if(on){deg+=[-2,-1,-1,1,1,2,0,3,-3][Math.floor(r()*9)];deg=Math.max(-2,Math.min(9,deg));out.push({s,deg,len:s%4===0&&r()<.5?3:1})}}return out};
  const A=motif(),B=motif();tr.mel=[A,A.map(n=>({...n,deg:n.s>=24?n.deg+(r()<.5?1:-1):n.deg})),B,A];
  const sc2=sc;tr.note=deg=>{const o=Math.floor(deg/7),i=((deg%7)+7)%7;return tr.key+12*o+sc2[i]}}
 function ri2(r,a,b){return a+Math.floor(r()*(b-a+1))}
 const M={cur:null,name:'',step:0,next:0,on:false,speed:1,
  play(n){if(this.name===n)return;this.name=n;this.cur=T[n]||null;if(this.cur)compose(this.cur);this.step=0;this.on=false},
  tick(){const c=AU.ctx;if(!c||c.state!=='running'||!this.cur)return;const want=save.music&&!hidden&&!save.muted;if(!want){this.on=false;return}
   if(!this.on||this.next<c.currentTime-.3){this.on=true;this.next=c.currentTime+.08}
   const tr=this.cur,sd=60/(tr.bpm*this.speed)/4;while(this.next<c.currentTime+.2){this.note(this.step,this.next,sd);this.next+=sd*(tr.drums==='swing'?(this.step%2?.8:1.2):1);this.step++}},
  note(st,t,sd){const tr=this.cur,c=AU.ctx,d=AU.mus;const bar=Math.floor(st/16)%8,s=st%16;const sc=SC[tr.sc];const deg=tr.prog[bar];const root=tr.key+sc[deg%7]-12;
   const chord=[0,2,4].map(k=>tr.note(deg+k));
   const env=(g,a,v,dur)=>{g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+a);g.gain.exponentialRampToValueAtTime(.0001,t+dur)};
   const o=(type,f,dur,v,a=.008,filt=0,det=0)=>{const os=c.createOscillator(),g=c.createGain();os.type=type;os.frequency.value=f;if(det)os.detune.value=det;let n=os;if(filt){const fl=c.createBiquadFilter();fl.type='lowpass';fl.frequency.setValueAtTime(filt,t);fl.frequency.exponentialRampToValueAtTime(Math.max(200,filt*.3),t+dur);os.connect(fl);n=fl}n.connect(g);g.connect(d);env(g,a,v,dur);os.start(t);os.stop(t+dur+.05)};
   const inst={marimba:(m,dur)=>{o('sine',mf(m),Math.min(.5,dur),.22,.004);o('sine',mf(m)*4,.08,.05,.002)},
    bell:(m,dur)=>{o('sine',mf(m),dur*1.6,.16,.004);o('sine',mf(m)*2.76,dur*.6,.05,.002);o('triangle',mf(m+12),dur,.03,.01)},
    pluck:(m,dur)=>{o('sawtooth',mf(m),Math.min(.4,dur),.12,.004,3200)},
    whistle:(m,dur)=>{const os=c.createOscillator(),g=c.createGain(),lf=c.createOscillator(),lg=c.createGain();os.type='sine';os.frequency.value=mf(m+12);lf.frequency.value=6;lg.gain.value=8;lf.connect(lg);lg.connect(os.frequency);os.connect(g);g.connect(d);env(g,.05,.12,dur*1.1);os.start(t);lf.start(t);os.stop(t+dur*1.1+.05);lf.stop(t+dur*1.1+.05)},
    brass:(m,dur)=>{o('sawtooth',mf(m),dur,.09,.03,2600,-6);o('sawtooth',mf(m),dur,.07,.03,2600,7)},
    square:(m,dur)=>{o('square',mf(m),dur,.07,.005,4200)}};
   // drums
   const kick=()=>{const os=c.createOscillator(),g=c.createGain();os.frequency.setValueAtTime(150,t);os.frequency.exponentialRampToValueAtTime(42,t+.12);g.gain.setValueAtTime(.55,t);g.gain.exponentialRampToValueAtTime(.001,t+.16);os.connect(g);g.connect(d);os.start(t);os.stop(t+.18)};
   const snare=v=>AU.noise(.12,v||.2,1900,'bandpass',0,null,d,t);const hat=v=>AU.noise(.035,v||.06,8000,'highpass',0,null,d,t);
   const dr=tr.drums;
   if(dr==='pop'){if(s%8===0)kick();if(s%8===4)snare();if(s%2===1)hat()}
   else if(dr==='soft'){if(s===0)kick();if(s===8)snare(.08);if(s%4===2)hat(.04)}
   else if(dr==='swing'){if(s%8===0||s===14)kick();if(s%8===4)snare(.14);if(s%2===0)hat(.05)}
   else if(dr==='gallop'){if(s%4===0)kick();if(s%4===3||s%4===1)hat(.07);if(s%8===4)snare(.15)}
   else if(dr==='march'){if(s%4===0)kick();if(s%8===4||s===14||s===15)snare(.16);if(s%2===1)hat(.04)}
   else if(dr==='rock'){if(s%8===0||s%8===3||s===10)kick();if(s%8===4)snare(.24);hat(s%2?.04:.07)}
   // bass
   const bs=tr.bass,b=m=>{o('triangle',mf(m),sd*1.8,.32,.006);o('sawtooth',mf(m),sd*1.2,.05,.006,900)};
   if(bs==='round'){if(s===0||s===8)b(root);if(s===12)b(root+7)}
   else if(bs==='bounce'){if(s%4===0)b(root+(s===8?7:0));if(s%4===2)b(root+12)}
   else if(bs==='swamp'){if(s===0||s===6||s===10)b(root);if(s===14)b(root+3)}
   else if(bs==='gallop'){if(s%4===0)b(root);if(s%4===3)b(root+7)}
   else if(bs==='march'){if(s%4===0)b(root+(s%8?7:0))}
   else if(bs==='drive'){if(s%2===0)b(root+(s===12?3:0))}
   // pad / chords
   if(tr.pad&&s===0)chord.forEach((m,i)=>{o('sawtooth',mf(m),sd*15,.022,.25,1400,i*4-4)});
   else if(!tr.pad&&(s===4||s===12))chord.forEach(m=>o('triangle',mf(m),sd*1.5,.045,.006));
   // lead melody
   const ph=Math.floor(bar/2)%4,sub=(bar%2)*16+s;const mel=tr.mel[ph];for(const n of mel)if(n.s===sub){const m=tr.note(n.deg+7);(inst[tr.lead]||inst.square)(m+(tr.lead==='brass'?-12:0),sd*(n.len+.6))}}};
 return M})();

/* ===== Giraffe SFX: squeals, muffled squeals, boing, splat, Nooooo! (all synthesized) ===== */
AU.filt=function(type,f,q){const c=this.ctx;if(!c)return null;const fl=c.createBiquadFilter();fl.type=type;fl.frequency.value=f;fl.Q.value=q||.7;fl.connect(this.sfx);return fl};
AU.voice=function(f0,f1,d,v,opt){const c=this.ctx;if(!c)return;opt=opt||{};const t=c.currentTime+(opt.dl||0);
 const o=c.createOscillator(),o2=c.createOscillator(),g=c.createGain(),lfo=c.createOscillator(),lg=c.createGain();
 o.type=opt.type||'sawtooth';o2.type='square';o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(30,f1),t+d);
 o2.frequency.setValueAtTime(f0*1.005,t);o2.frequency.exponentialRampToValueAtTime(Math.max(30,f1*1.005),t+d);
 lfo.frequency.value=opt.vib||7;lg.gain.value=f0*(opt.vd||.03);lfo.connect(lg);lg.connect(o.frequency);lg.connect(o2.frequency);
 const dest=opt.dest||AU.filt('bandpass',opt.formant||1600,opt.fq||1.6);if(!dest)return;
 const g2=c.createGain();g2.gain.value=.35;o.connect(g);o2.connect(g2);g2.connect(g);g.connect(dest);
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+.03);if(opt.hold)g.gain.setValueAtTime(v,t+d*opt.hold);g.gain.exponentialRampToValueAtTime(.0001,t+d);
 if(opt.formEnd&&dest.frequency)dest.frequency.exponentialRampToValueAtTime(opt.formEnd,t+d);
 [o,o2,lfo].forEach(x=>{x.start(t);x.stop(t+d+.05)})};
let _sq=0;
Object.assign(SFX,{
 squeal(){const P=[[1250,1700],[1500,2000],[1100,1550],[1700,2250]][(_sq++)%4];const j=1+(Math.random()-.5)*.12;
  AU.voice(P[0]*j,P[1]*j,.22,.11,{formant:2600,fq:1.2,vib:18,vd:.04});AU.voice(P[1]*j,P[0]*j*1.1,.2,.09,{dl:.2,formant:2800,fq:1.2,vib:22,vd:.05})},
 squealMuffled(){const b=1200+Math.random()*400;const lp=AU.filt('lowpass',420,4);if(!lp)return;
  AU.voice(b,b*1.25,.28,.16,{dest:lp,vib:16,vd:.05});AU.voice(b*1.2,b*.9,.32,.13,{dest:lp,dl:.3,vib:20,vd:.05});AU.noise(.12,.05,300,'lowpass',.05)},
 boing(){AU.tone(150,.32,'sine',.22,520);AU.tone(240,.26,'triangle',.09,760,.03);AU.tone(500,.12,'sine',.06,1100,.18)},
 strain(){AU.tone(95,.14,'sawtooth',.06,80);AU.noise(.1,.05,700,'bandpass')},
 splat(){AU.noise(.2,.22,1100,'lowpass',0,180);AU.tone(260,.14,'sine',.14,70);AU.tone(700,.16,'sine',.06,1500,.08);AU.noise(.08,.07,2600,'bandpass',.14)},
 slurpDrool(){AU.tone(900,.16,'sine',.1,300);AU.tone(420,.12,'triangle',.06,900,.07)},
 nooo(){const j=1+(Math.random()-.5)*.1;AU.voice(820*j,240*j,1.45,.13,{formant:900,formEnd:420,fq:2.2,vib:6,vd:.03,hold:.35})}
});

