function spawnGems(x,y,n,ci){for(let i=0;i<n;i++){const a=rand(-2.6,-.5),s=rand(140,300);gems.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,t:0,ci:ci<0?ri(0,4):ci,rot:rand(0,6),rainbow:ci<0})}}
function celebrate(){for(let i=0;i<120;i++)parts.push({x:rand(0,W),y:rand(-H*.3,-10),vx:rand(-60,60),vy:rand(80,260),g:120,life:rand(2,3.5),t:0,r:rand(3,6),c:['#ff4f6e','#3aa8ff','#56d04f','#ffcc2e','#a866ff','#fff'][ri(0,5)],ty:'conf',rot:rand(0,6)})}
let gemK=0,gemKT=0;
function updFx(dt){for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.t+=dt;if(p.t>=p.life){parts.splice(i,1);continue}p.vy+=p.g*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=1-dt*1.5;if(p.rot!=null)p.rot+=dt*6}
 for(let i=labels.length-1;i>=0;i--){const l=labels[i];l.t+=dt;if(l.t>l.life)labels.splice(i,1)}
 gemKT-=dt;if(gemKT<0)gemK=0;
 if(!G)return;const K=G.kelly,mx=K.x,my=GE.kY-GE.kH*.45;
 for(let i=gems.length-1;i>=0;i--){const g=gems[i];g.t+=dt;g.rot+=dt*5;if(g.t<.32){g.vy+=500*dt;g.x+=g.vx*dt;g.y+=g.vy*dt}else{const dx=mx-g.x,dy=my-g.y,d=Math.hypot(dx,dy)||1;const sp=380+(g.t-.32)*1800;g.vx=lerp(g.vx,dx/d*sp,Math.min(1,dt*10));g.vy=lerp(g.vy,dy/d*sp,Math.min(1,dt*10));g.x+=g.vx*dt;g.y+=g.vy*dt;
   if(d<18||g.t>2.5){gems.splice(i,1);G.gemsN++;G.score+=5;SFX.gem(gemK++);gemKT=.4;K.mouth=Math.max(K.mouth,.6);parts.push({x:mx,y:my,vx:0,vy:0,g:0,life:.18,t:0,r:10,c:'#fff7b0',ty:'ring'})}}}
 const bb=GE.bossBox;for(let i=orbs.length-1;i>=0;i--){const o=orbs[i];o.t+=dt;if(!bb||!G.boss){orbs.splice(i,1);continue}const tx=bb.x,ty=bb.y-bb.h*.5;
  if(o.t<.25){o.vy+=300*dt;o.x+=o.vx*dt;o.y+=o.vy*dt}else{const dx=tx-o.x,dy=ty-o.y,d=Math.hypot(dx,dy)||1;const sp=500+(o.t-.25)*2400;o.vx=lerp(o.vx,dx/d*sp,Math.min(1,dt*9));o.vy=lerp(o.vy,dy/d*sp,Math.min(1,dt*9));o.x+=o.vx*dt;o.y+=o.vy*dt;
   if(d<24||o.t>2){orbs.splice(i,1);hurtBoss(o.d,o.x,o.y);SFX.hit(ri(0,4));spark(o.x,o.y,o.c,6);parts.push({x:o.x,y:o.y,vx:0,vy:0,g:0,life:.2,t:0,r:22,c:o.c,ty:'glow'});if(!orbs.length&&G.boss.hp<=0)setTimeout(()=>{if(G&&!G.over&&!G.res)afterSettle()},900)}}}}
