const GP={on:false};let gpPrev={},gpCount=0,gpNavT=0,gpIdx=0,gpRep=0;
addEventListener('gamepadconnected',e=>{toast('🎮 Controller connected'+(e.gamepad&&e.gamepad.id?': '+e.gamepad.id.split('(')[0].trim().slice(0,32):''));gpCount++;GP.on=true;gpFocus(gpIdx)});
