function clearGP(){gpPrev={}}
function gpFocus(i,kb){const bs=[...document.querySelectorAll('#ui [data-a]')];document.querySelectorAll('#ui .gpf').forEach(b=>b.classList.remove('gpf'));if(!bs.length||!(GP.on||kb||kbNav))return;gpIdx=(i+bs.length)%bs.length;bs[gpIdx].classList.add('gpf');bs[gpIdx].scrollIntoView({block:'nearest'})}
function pollGamepad(dt){let pads=[];try{pads=navigator.getGamepads?[...navigator.getGamepads()].filter(Boolean):[]}catch(e){}
 if(pads.length&&!GP.on){GP.on=true;if(!gpCount){toast('🎮 Controller connected');gpCount++}gpFocus(gpIdx)}
 if(!pads.length){if(GP.on){GP.on=false;clearGP()}return}
 const pd=pads[0];const b=i=>!!(pd.buttons[i]&&(pd.buttons[i].pressed||pd.buttons[i].value>0.5));const ax=i=>pd.axes[i]||0;const x=ax(0),y=ax(1);
 const cur={A:b(0),B:b(1),X:b(2),Y:b(3),LB:b(4),RB:b(5),ST:b(9),BK:b(8),DU:b(12)||y<-.55,DD:b(13)||y>.55,DL:b(14)||x<-.55,DR:b(15)||x>.55};
 const pr=k=>cur[k]&&!gpPrev[k];if(Object.values(cur).some(v=>v))AU.unlock();
 if(state==='play'&&G){const dir=cur.DL?-1:cur.DR?1:0;if(dir){if(pr(dir<0?'DL':'DR')){moveKelly(dir);gpRep=.28}else{gpRep-=dt;if(gpRep<=0){moveKelly(dir);gpRep=.11}}}
  if(pr('A')||pr('DU'))act();if(pr('X')||pr('RB')){if(G.mode==='puzzle')undo();else useBurp()}if(pr('Y')||pr('LB'))hint();if(pr('ST'))pauseGame();if(pr('B')&&G.mode==='puzzle')undo()}
 else if(document.body.classList.contains('uiopen')){gpNavT-=dt;const nav=(cur.DD||cur.DR)?1:(cur.DU||cur.DL)?-1:0;
  if(nav&&(gpNavT<=0)){gpFocus(gpIdx+nav);gpNavT=gpPrev._nav?0.16:0.32;SFX.menu()}if(!nav)gpNavT=0;cur._nav=nav;
  if(pr('A')){const bs=[...document.querySelectorAll('#ui [data-a]')];const t=bs[gpIdx]||bs[0];if(t)t.click()}
  else if(pr('B')){if(state==='pause')resumeGame();else{const bk=UI.querySelector('[data-a="howx"],[data-a="title"],[data-a="map"],[data-a="tower"],[data-a="skip"]');if(bk&&state!=='title')bk.click()}}
  else if(pr('ST')){if(state==='pause')resumeGame();else if(state==='title'){const t=UI.querySelector('[data-a="adventure"]');if(t)t.click()}}}
 gpPrev=cur}

/* ===== main loop, autopilot (QA), boot ===== */
let lastT=performance.now(),BOT=null,TSCALE=1;
function frame(dt){RT+=dt;pollGamepad(dt);MUS.tick();
 if(state==='play'&&G){if(G.hitstop>0){G.hitstop-=dt;dt*=.15}G.shake=Math.max(0,G.shake-dt*30);updateGame(dt);updateVis(dt);updFx(dt);if(BOT)botTick(dt);
  if(G.over&&G.overT>(G.over.win?2.1:1.4)&&state==='play')showResult();
  const bb=$('bBurp');if(bb&&!bb.hidden){const t='BURP ×'+G.burps;if(bb.textContent!==t)bb.textContent=t;bb.disabled=G.burps<=0}
  const bu=$('bUndo');if(bu&&!bu.hidden)bu.disabled=!G.undo.length}
 else if(state==='pause'&&G){}
 const wi=G?G.w:(state==='map'||state==='tower'?(Math.floor(RT/12)%5):state==='card'?STAGES[cardStage].w:4);updMotes(dt,WORLDS[wi].mote);
 X.setTransform(DPR,0,0,DPR,0,0);drawBG(wi,G?(state==='play'?.08:.35):.25);drawMotes(WORLDS[wi].mote,false);
 if(G&&GE&&(state==='play'||state==='pause'||state==='result')){drawWorld();drawMotes(WORLDS[wi].mote,true);drawHUD();drawOverlayText()}else drawMotes(WORLDS[wi].mote,true)}
function loop(now){requestAnimationFrame(loop);const dt=Math.min(.05,Math.max(0,(now-lastT)/1000));lastT=now;if(hidden)return;try{for(let i=0;i<TSCALE;i++)frame(dt)}catch(e){(window.__ERR=window.__ERR||[]).push(String(e&&e.stack||e));console.error(e)}}
document.addEventListener('visibilitychange',()=>{hidden=document.hidden;if(hidden&&state==='play')pauseGame();if(AU.ctx){if(hidden)AU.ctx.suspend().catch(()=>{});else AU.ctx.resume().catch(()=>{})}});
/* ---- autopilot: plays like a person (one decision at a time, real swipes/taps, no cheats) ---- */
function botTick(dt){const B=BOT;B.t-=dt;if(B.t>0||!G||G.over||state!=='play')return;
 if(G.hold){if(B.to==null){B.to=G.kelly.col}if(G.kelly.col!==B.to){setKellyCol(G.kelly.col+(B.to>G.kelly.col?1:-1));B.t=B.step;return}if(!G.tg){act();B.to=null;B.t=B.think}return}
 if(B.plan){if(G.kelly.col!==B.plan[0]){setKellyCol(G.kelly.col+(B.plan[0]>G.kelly.col?1:-1));B.t=B.step;return}if(!canAct()||busy()){return}B.to=B.plan[1];B.plan=null;act();B.t=B.step;return}
 if(!canAct()||busy())return;
 let best=null;if(G.mode==='puzzle'){const r=hintMoves();if(r.moves&&r.moves.length)best=r.moves[0]}
 if(!best){const ev=(Bd,f,t)=>{const N=KC.clone(Bd);const r=KC.move(N,f,t);if(!r)return[N,-1e9];const tall=Math.max(...N.map(c=>c.length));return[N,r.settle.popped*10+r.settle.chain*30-(tall>G.MAXR-3?tall*10:0)+(r.spit.kind==='eat'?5:0)-KC.count(N)*.5]};let bs=-1e9;
  const legal=KC.legal(G.B).filter(([f,t])=>f!==t&&!(G.frozen[f]>0)&&!(G.frozen[t]>0));
  for(const [f,t] of legal){const [N,s1]=ev(G.B,f,t);let s2=-5;for(const [f2,t2] of KC.legal(N)){if(f2===t2)continue;const q=ev(N,f2,t2)[1];if(q>s2)s2=q}const sc=s1+.8*s2+Math.random()*2-Math.abs(f-G.kelly.col)*.3;if(sc>bs){bs=sc;best=[f,t]}}
  if(G.burps>0&&G.danger>.6&&!busy()){useBurp();B.t=B.think;return}}
 if(!best){B.t=.3;return}B.plan=best;B.t=B.step}
function hintMoves(){const left=G.limit-G.moves,on=onPath(G.B,left);if(on)return{moves:on};const s=hintSearch(G.B,left,400000);let r;while(!(r=s.step(1e9)));return r}
